using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("Compiling=" + UnityEditor.EditorApplication.isCompiling + " CompileFailed=" + UnityEditor.EditorUtility.scriptCompilationFailed + " SceneDirty=" + UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty);
            if (UnityEditor.EditorUtility.scriptCompilationFailed)
                throw new System.Exception("Project script compilation failed");
        }
    }
}
